import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/Year Input',
  component: 'bfl-year-input',
  tags: ['autodocs'],
  argTypes: {
    name: {
      control: 'text',
      description: 'Name of the field (required for bfl-form-wrapper to identify it)',
      defaultValue: 'year',
    },
    label: {
      control: 'text',
      description: 'Label for the Year input field',
      defaultValue: 'Year',
    },
    placeholder: {
      control: 'text',
      description: 'Placeholder text for the input field',
      defaultValue: 'YYYY',
    },
    value: {
      control: 'text',
      description: 'Value of the Year input field',
      defaultValue: '',
    },
    hasCustomError: {
      control: 'boolean',
      description: 'Indicates if the input field has a custom error',
      defaultValue: false,
    },
    customErrorMessage: {
      control: 'text',
      description: 'Custom error message to display when the Year is invalid',
      defaultValue: 'Invalid year',
    },
    isAutoFill: {
      control: 'boolean',
      description: 'Indicates if the input field should be autofilled',
      defaultValue: false,
    },
    grayOutFieldWithDisabled: {
      control: 'boolean',
      description: 'Indicates if the input field should be grayed out when disabled',
      defaultValue: false,
    },
  },
};

const Template = ({ name, label, placeholder, value, hasCustomError, customErrorMessage }) => html`
  <bfl-year-input
    name="${name}"
    label="${label}"
    placeholder="${placeholder}"
    value="${value}"
    has-custom-error="${hasCustomError}"
    custom-error-message="${customErrorMessage}"
    @input-changed="${action('inputChanged')}"
  ></bfl-year-input>
`;

